// Extrae el mensaje del payload de Evolution y decide si se procesa.
// Filtra mensajes propios, grupos, vacíos y números no autorizados.

// ---- LISTA BLANCA ----
// Formato internacional, sin +, guiones ni espacios.
const AUTORIZADOS = [
  '50248664480', // Ana Waight
  '50232134653', // Altan Ozler
  '50258077538', // Jeffrey Chitamul
  '50240582026', // Felipe Castañeda
  '50230694290', // Axel Sambrano
];

// Array vacío [] permite cualquier número.
// No es recomendable para producción.

// Obtener payload de Evolution API
const entrada = $input.first().json;
const b = entrada.body || entrada;
const d = b.data || {};
const k = d.key || {};

// Evolution puede entregar:
// remoteJidAlt = número real, por ejemplo 50230694290@s.whatsapp.net
// remoteJid    = LID interno, por ejemplo 65580526751932@lid
const remoteJid = (k.remoteJid || '').toString();
const remoteJidAlt = (k.remoteJidAlt || '').toString();

// Priorizar siempre remoteJidAlt cuando esté disponible
const jid = remoteJidAlt || remoteJid;

// Extraer únicamente el número
const numero = jid
  .replace('@s.whatsapp.net', '')
  .replace('@c.us', '')
  .replace('@lid', '')
  .replace(/\D/g, '');

// Detectar grupos usando ambos campos
const esGrupo =
  remoteJid.includes('@g.us') ||
  remoteJidAlt.includes('@g.us');

const propio = k.fromMe === true;

// Extraer texto de los formatos más comunes de WhatsApp
const texto = (
  d.message?.conversation ||
  d.message?.extendedTextMessage?.text ||
  d.message?.imageMessage?.caption ||
  d.message?.videoMessage?.caption ||
  ''
).toString().trim();

// Validar lista blanca
const autorizado =
  AUTORIZADOS.length === 0 ||
  AUTORIZADOS.includes(numero);

// Decidir si se procesa
const procesar =
  !propio &&
  !esGrupo &&
  texto.length > 0 &&
  autorizado;

// Resultado para los siguientes nodos
return [{
  json: {
    procesar,
    numero,
    texto,
    jid,
    remoteJid,
    remoteJidAlt,
    sesion: numero,
    token: Date.now().toString(),
    motivo: propio
      ? 'propio'
      : esGrupo
        ? 'grupo'
        : !texto
          ? 'vacio'
          : !autorizado
            ? 'no-autorizado'
            : 'ok'
  }
}];

// Analiza el mensaje: intencion, periodo, unidad, region y detalle.

const e = $('Preparar entrada').first().json;
const msg = e.texto.toLowerCase().trim();
const sesion = e.sesion;
const numero = e.numero;

const MESES = { enero:1, febrero:2, marzo:3, abril:4, mayo:5, junio:6,
  julio:7, agosto:8, septiembre:9, setiembre:9, octubre:10,
  noviembre:11, diciembre:12 };

const REGIONES = ['occidente','centro','oriente','walmart','gta',
  'la bodegona','comercial los hermanos','tiendas de oriente',
  'unisuper','pricesmart','distribuidores','institucional',
  'internacional','tomsal honduras','tomsal el salvador',
  'tomsal nicaragua','tradicional','moderno','tomsales','guatemala'];

// ---------- intencion ----------
const PALABRAS = ['venta','vendi','ppto','presupuesto','reporte','resumen',
  'como vamos','cómo vamos','como va','cómo va','cumplimiento','meta',
  'cajas','valores','cartera','activacion','activación','region','región',
  'gerencia','desempeño','desempeno','vs aa','año anterior','ano anterior',
  'cuanto','cuánto','mes pasado','detalle','peor','mejor'];

let esConsulta = PALABRAS.some(p => msg.includes(p))
              || Object.keys(MESES).some(m => msg.includes(m))
              || REGIONES.some(r => msg.includes(r))
              || /\b20\d{2}\b/.test(msg);

const CHARLA = ['hola','buenas','buen dia','buen día','buenos dias',
  'buenos días','buenas tardes','buenas noches','gracias','ok','listo',
  'adios','adiós','hasta luego','que tal','qué tal','quien sos','quién sos',
  'quien eres','quién eres','que haces','qué haces','ayuda','help','menu','menú'];
const esCharla = CHARLA.some(c => msg === c || msg.startsWith(c + ' ')
                                || msg.startsWith(c + ',') || msg.endsWith(' ' + c));
if (esCharla && !Object.keys(MESES).some(m => msg.includes(m))) esConsulta = false;
if (msg.length < 3) esConsulta = false;

// ---------- periodo ----------
const hoy = new Date();
let anio = hoy.getFullYear();
let mes  = hoy.getMonth() + 1;

for (const [nombre, num] of Object.entries(MESES)) {
  if (msg.includes(nombre)) { mes = num; break; }
}
const mAnio = msg.match(/\b(20\d{2})\b/);
if (mAnio) anio = parseInt(mAnio[1], 10);
if (msg.includes('mes pasado') || msg.includes('mes anterior')) {
  mes = mes - 1;
  if (mes === 0) { mes = 12; anio = anio - 1; }
}

// saneo: evita inyeccion SQL
anio = Math.min(Math.max(parseInt(anio,10) || 2026, 2019), 2030);
mes  = Math.min(Math.max(parseInt(mes,10)  || 1, 1), 12);

// ---------- unidad ----------
const unidad = (msg.includes('valor') || msg.includes('quetzal')
             || msg.includes('dinero') || msg.includes('factur')
             || msg.includes('monto')  || msg.includes('ingreso')
             || msg.includes('vendimos en q')
             || msg.includes('venta en q') || / en q\b/.test(msg))
             ? 'valores' : 'cajas';

// ---------- filtro ----------
let filtro = null;
for (const r of REGIONES) {
  if (msg.includes(r)) { filtro = r.toUpperCase(); break; }
}
const cuantas = REGIONES.filter(r => msg.includes(r)).length;
if (cuantas > 1 || msg.includes('compar') || msg.includes('peor')
   || msg.includes('mejor') || msg.includes('ranking')) filtro = null;

// ---------- detalle ----------
const detalle = msg.includes('detalle') || msg.includes('todas')
             || msg.includes('todo') || msg.includes('por region')
             || msg.includes('por región') || msg.includes('completo')
             || filtro !== null;


// ---------- detalle por vendedor / cliente / familia / producto ----------
// Palabras que abren la consulta de detalle. Si no aparece ninguna,
// nivel = null y el flujo sigue como siempre (resumen + imagen).
const NIVELES = [
  { nivel: 'VENDEDOR', claves: ['vendedores','vendedor','por vendedor','ruteros'] },
  { nivel: 'CLIENTE',  claves: ['clientes','cliente','por cliente','cadena'] },
  { nivel: 'PRODUCTO', claves: ['productos','producto','sku','presentacion','presentación'] },
  { nivel: 'FAMILIA',  claves: ['familias','familia','por familia','linea','línea'] },
];

let nivel = null, termino = null;
for (const n of NIVELES) {
  for (const k of n.claves) {
    const i = msg.indexOf(k);
    if (i >= 0) {
      nivel = n.nivel;
      // lo que viene despues de la palabra es el termino de busqueda
      let resto = msg.slice(i + k.length);
      resto = resto.replace(/^[\s:,]*(de|del|la|el|los|las|en)\s+/i, '').trim();
      resto = resto.replace(/[?¿!¡.,;]+$/g, '')
                   .replace(/\b(en\s+)?(cajas|valores|quetzales|q)\b.*$/i, '')
                   .replace(/\b(de|en)\s+(enero|febrero|marzo|abril|mayo|junio|julio|agosto|septiembre|setiembre|octubre|noviembre|diciembre).*$/i, '')
                   .replace(/\b20\d\d\b.*$/, '')
                   .trim();
      // solo letras, numeros y espacios: evita inyeccion en el EXEC
      resto = resto.replace(/[^a-z0-9ñáéíóúü ]/gi, '').trim().slice(0, 60);
      if (resto.length >= 3) termino = resto;
      break;
    }
  }
  if (nivel) break;
}

// cuantas filas: por defecto 10; "top 5", "los 15"
let top = 10;
const mTop = msg.match(/\b(?:top|primeros|mejores|los)\s+(\d{1,2})\b/);
if (mTop) top = Math.min(25, Math.max(3, parseInt(mTop[1], 10)));
// "peores" / "mas bajos" -> los de menor venta
if (/\b(peores|mas bajos|más bajos|menor venta|ultimos|últimos)\b/.test(msg)) top = -top;

// ---------- cache ----------
// el mes en curso NO se cachea: cambia durante el dia
const esMesActual = (anio === hoy.getFullYear() && mes === hoy.getMonth() + 1);
// mes en curso: cache corto de 5 minutos (TTL 300s en Cache SET),
// asi todos los que pregunten en esa ventana ven la misma cifra
// y NAV recibe una sola consulta.
// meses cerrados: cache de 12 horas.
const cacheKey = esMesActual
  ? `reporte:vivo:${anio}:${String(mes).padStart(2,'0')}`
  : `reporte:${anio}:${String(mes).padStart(2,'0')}`;

return [{ json: {
  esConsulta, anio, mes, unidad, filtro, detalle,
  nivel, termino, top,
  esMesActual, cacheKey, pregunta: msg, sesion, numero
}}];

// Respuesta directa: no toca SQL, no llama al modelo, no cuesta tokens.

const p = $input.first().json;
const m = (p.pregunta || '').toLowerCase();

let r;

if (m.includes('gracias')) {

  r = 'Con gusto. Quedo atento a cualquier otra consulta.';

} else if (
  m.includes('ayuda') ||
  m.includes('menu') ||
  m.includes('menú') ||
  m.includes('help') ||
  m.includes('que haces') ||
  m.includes('qué haces') ||
  m.includes('quien') ||
  m.includes('quién')
) {

  r = '*LIB-IA · Asistente de Ventas e Inteligencia Comercial*\n\n'
    + 'Hola. Soy *LIB-IA*, asistente virtual de ventas e inteligencia comercial.\n\n'
    + 'Estoy disponible para apoyarle con consultas sobre resultados de ventas, desempeño comercial y análisis de indicadores clave por país, región y gerencia.';

} else if (
  m.includes('adios') ||
  m.includes('adiós') ||
  m.includes('hasta luego')
) {

  r = 'Gracias por utilizar LIB-IA. Hasta luego.';

} else {

  r = 'Hola. Soy *LIB-IA*, asistente virtual de ventas e inteligencia comercial.\n\n'
    + 'Estoy disponible para apoyarle con consultas sobre resultados de ventas, desempeño comercial y análisis de indicadores clave por país, región y gerencia.';

}

return [{
  json: {
    output: r,
    numero: p.numero,
    tipo: 'charla'
  }
}];

