// Normaliza el origen (cache o SQL), aplica el filtro y devuelve N items.

const p = $('Analizar mensaje').first().json;
let filas = null;

try {
  const c = $('Cache GET').first().json.cache;
  if (c && typeof c === 'string' && c.startsWith('[')) filas = JSON.parse(c);
} catch (e) { /* sin cache */ }

if (!filas) {
  try { filas = $('SQL Reporte').all().map(i => i.json); } catch (e) { filas = []; }
}

filas = (filas || []).filter(f => f && f.Region
         && f.Pais !== '(SIN RESOLVER)'
         && f.Region !== '(SIN RESOLVER)');

if (!filas.length) {
  return [{ json: { _vacio: true, anio: p.anio, mes: p.mes } }];
}

if (p.filtro) {
  const f = filas.filter(r => r.Region === p.filtro
                           || r.Gerencia === p.filtro
                           || r.Pais === p.filtro);
  if (f.length) filas = f;
}

return filas.map(f => ({ json: f }));

// Arma la tarjeta y el contexto. Devuelve UN item.
// Formato WhatsApp completo: negritas, cursivas, block quote (>) y
// monospace (```) que preserva el espaciado y permite tablas alineadas.

const p     = $('Analizar mensaje').first().json;
const filas = $input.all().map(i => i.json).filter(f => f && f.Region);

// Orden del dashboard. NO es alfabetico: es orden de negocio.
const ORDEN_PAIS = ['GUATEMALA','ESTADOS UNIDOS','CENTROAMERICA'];
const ORDEN_GER  = ['TRADICIONAL','MODERNO','DISTRIBUIDORES',
                    'INSTITUCIONAL','INTERNACIONAL','TOMSALES'];
const pos = (v, l) => { const i = l.indexOf(v); return i < 0 ? l.length : i; };

const MESES = ['','enero','febrero','marzo','abril','mayo','junio',
  'julio','agosto','septiembre','octubre','noviembre','diciembre'];
const periodo = `${MESES[p.mes]} ${p.anio}`;

// pais > gerencia (orden de negocio), region por presupuesto desc
const ordenarFilas = (arr, P) => arr.slice().sort((a,b) =>
  pos(a.Pais, ORDEN_PAIS) - pos(b.Pais, ORDEN_PAIS)
  || pos(a.Gerencia, ORDEN_GER) - pos(b.Gerencia, ORDEN_GER)
  || P(b) - P(a));

if (!filas.length) {
  return [{ json: {
    tarjeta:  `No hay información para ${periodo}.`,
    contexto: `SIN DATOS para ${periodo}.`,
    pregunta: p.pregunta, sesion: p.sesion, numero: p.numero, filas: 0
  }}];
}

const esCajas = p.unidad === 'cajas';
const u = esCajas ? 'cajas' : 'Q';

const n = (v) => Math.round(Number(v) || 0).toLocaleString('es-GT');
// abrevia solo valores; las cajas se leen mejor completas
const corto = (v) => {
  if (esCajas) return Math.round(v).toLocaleString('es-GT');
  if (Math.abs(v) >= 1e6) return (v/1e6).toFixed(1) + 'M';
  if (Math.abs(v) >= 1e3) return (v/1e3).toFixed(0) + 'K';
  return Math.round(v).toString();
};
const sem = (x) => x >= 100 ? '🟢' : x >= 85 ? '🟡' : '🔴';
const mk  = (x) => x >= 100 ? '+'  : x >= 85 ? '~'  : '!';

const V  = (f) => esCajas ? f.Venta_Cajas   : f.Venta_Valores;
const P  = (f) => esCajas ? f.Ppto_Cajas    : f.Ppto_Valores;
const L  = (f) => esCajas ? f.LY_Cajas      : f.LY_Valores;
const PP = (f) => esCajas ? f.PctPpto_Cajas : f.PctPpto_Valores;
const PA = (f) => esCajas ? f.PctAA_Cajas   : f.PctAA_Valores;
// columnas del mes en curso; vienen NULL cuando el mes ya cerro
const PED = (f) => esCajas ? f.Pedidos_Cajas    : f.Pedidos_Valores;
const MAS = (f) => esCajas ? f.MasPedidos_Cajas : f.MasPedidos_Valores;
const PAC = (f) => esCajas ? f.PptoPacing_Cajas : f.PptoPacing_Valores;

const vivo = filas[0].EsMesActual === 1 || filas[0].EsMesActual === true;
const dias = filas[0].DiasTranscurridos, diasMes = filas[0].DiasMes;

const tV = filas.reduce((a,f) => a + V(f), 0);
const tP = filas.reduce((a,f) => a + P(f), 0);
const tL = filas.reduce((a,f) => a + L(f), 0);
const tPct = tP ? (tV / tP * 100) : 0;
const tAA  = tL ? (tV / tL * 100 - 100) : 0;

const tPED = vivo ? filas.reduce((a,f) => a + (PED(f) || 0), 0) : null;
const tMAS = vivo ? filas.reduce((a,f) => a + (MAS(f) || 0), 0) : null;
const tPAC = vivo ? filas.reduce((a,f) => a + (PAC(f) || 0), 0) : null;
const tPctPac = (vivo && tPAC) ? (tV / tPAC * 100) : null;
const tPctMas = (vivo && tPAC) ? (tMAS / tPAC * 100) : null;

const ordenadas = ordenarFilas(filas, P);

// agrupado por gerencia
const porGer = {};
for (const f of ordenadas) {
  const g = porGer[f.Gerencia] || (porGer[f.Gerencia] = { v:0, p:0, l:0, pac:0 });
  g.v += V(f); g.p += P(f); g.l += L(f); g.pac += (PAC(f) || 0);
}
const gerencias = Object.entries(porGer)
  .map(([k,g]) => ({ nombre:k, v:g.v, p:g.p, pac:g.pac,
                     pct: g.p ? g.v/g.p*100 : 0,
                     aa:  g.l ? g.v/g.l*100-100 : 0 }))
  .sort((a,b) => pos(a.nombre, ORDEN_GER) - pos(b.nombre, ORDEN_GER));

// ───────────── TARJETA ─────────────
let card;

if (filas.length === 1) {
  // ── una sola region ──
  const f = filas[0];
  card  = `*${f.Region}*\n_${f.Pais} · ${f.Gerencia} · ${periodo}_\n\n`;
  card += `> Venta *${n(V(f))}* ${u}\n`;
  card += `> Meta  ${n(P(f))} ${u}\n`;
  card += `> ${sem(PP(f))} *${PP(f)}%* del presupuesto\n`;
  card += `> ${PA(f) >= 0 ? '▲' : '▼'} ${PA(f)}% vs año anterior\n`;
  if (vivo) {
    const pac = PAC(f), pp = pac ? (V(f)/pac*100) : 0;
    card += `>\n`;
    card += `> _Mes en curso · día ${dias} de ${diasMes}_\n`;
    card += `> Pedidos ${n(PED(f))} ${u}\n`;
    card += `> +PED    *${n(MAS(f))}* ${u}\n`;
    card += `> Meta al día ${n(Math.round(pac))}\n`;
    card += `> ${sem(pp)} *${pp.toFixed(1)}%* del ritmo esperado\n`;
  }
  card += `\nCartera ${n(f.Cartera)}  ·  Activación ${n(f.Activacion)}`;

} else if (p.detalle) {
  // ── detalle por region ──
  card  = `*DETALLE POR REGIÓN*\n_${periodo} · ${esCajas?'Cajas':'Valores'}_\n\n`;
  card += '```\n';
  card += 'REGIÓN'.padEnd(14) + 'VENTA'.padStart(7) + '%'.padStart(7) + '\n';
  card += '─'.repeat(28) + '\n';
  let ger = null;
  for (const f of ordenadas) {
    if (f.Gerencia !== ger) { ger = f.Gerencia; card += `${ger}\n`; }
    card += ('  ' + f.Region).slice(0,13).padEnd(14)
          + corto(V(f)).padStart(7)
          + (mk(PP(f)) + Math.round(PP(f))).padStart(7) + '\n';
  }
  card += '─'.repeat(28) + '\n';
  card += 'TOTAL'.padEnd(14) + corto(tV).padStart(7)
        + (mk(tPct) + Math.round(tPct)).padStart(7) + '\n';
  card += '```\n\n_+ sobre meta · ~ cerca · ! debajo_';

} else {
  // ── resumen: KPI + tabla por gerencia ──
  card  = `*RESUMEN TOTAL EMPRESA*\n_${periodo} · ${esCajas?'Cajas':'Valores'}_\n\n`;
  card += `> Venta *${n(tV)}* ${u}\n`;
  card += `> Meta  ${n(tP)} ${u}\n`;
  card += `> ${sem(tPct)} *${tPct.toFixed(1)}%* del presupuesto\n`;
  card += `> ${tAA >= 0 ? '▲' : '▼'} ${tAA.toFixed(1)}% vs año anterior\n`;
  if (vivo) {
    card += `>\n`;
    card += `> _Mes en curso · día ${dias} de ${diasMes}_\n`;
    card += `> Pedidos ${n(tPED)} ${u}\n`;
    card += `> +PED    *${n(tMAS)}* ${u}\n`;
    card += `> Meta al día ${n(Math.round(tPAC))}\n`;
    card += `> ${sem(tPctPac)} *${tPctPac.toFixed(1)}%* del ritmo esperado\n`;
    card += `> ${sem(tPctMas)} ${tPctMas.toFixed(1)}% con pedidos\n`;
  }
  card += `\n`;
  card += '```\n';
  card += 'GERENCIA'.padEnd(15) + 'VENTA'.padStart(7)
        + (vivo ? '%RITMO' : '%PPTO').padStart(7) + '\n';
  card += '─'.repeat(29) + '\n';
  for (const g of gerencias) {
    // en el mes en curso el % relevante es contra el ritmo esperado
    const x = vivo && g.pac ? (g.v / g.pac * 100) : g.pct;
    card += g.nombre.slice(0,14).padEnd(15)
          + corto(g.v).padStart(7)
          + (mk(x) + x.toFixed(1)).padStart(7) + '\n';
  }
  card += '```\n';
  card += vivo ? '_% contra el ritmo esperado al día de hoy_\n\n'
               : '\n';
  card += `_Escriba *detalle* para las ${filas.length} regiones_`;
}

// ───────────── CONTEXTO PARA EL AGENTE ─────────────
let ctx = `PERIODO: ${periodo} | UNIDAD: ${u}`;
if (p.filtro) ctx += ` | FILTRO: ${p.filtro}`;
ctx += `\nTOTAL: venta ${n(tV)}, presupuesto ${n(tP)}, `;
ctx += `cumplimiento ${tPct.toFixed(1)}%, vs año anterior ${tAA.toFixed(1)}%\n`;
if (vivo) {
  ctx += `MES EN CURSO: dia ${dias} de ${diasMes}. `;
  ctx += `Pedidos ${n(tPED)}, venta+pedidos ${n(tMAS)}, `;
  ctx += `meta proporcional a los dias ${n(Math.round(tPAC))}, `;
  ctx += `cumplimiento vs ese ritmo ${tPctPac.toFixed(1)}%. `;
  ctx += `IMPORTANTE: al comentar el mes en curso usa el cumplimiento `;
  ctx += `contra el ritmo esperado, no contra el presupuesto completo, `;
  ctx += `porque el mes aun no termina.\n`;
}
ctx += `\n`;
ctx += `POR GERENCIA:\n`;
for (const g of gerencias) {
  ctx += `- ${g.nombre}: venta ${n(g.v)}, ppto ${n(g.p)}, `;
  ctx += `cumplimiento ${g.pct.toFixed(1)}%, vs AA ${g.aa.toFixed(1)}%\n`;
}
ctx += `\nPOR REGION:\n`;
for (const f of ordenadas) {
  ctx += `- ${f.Region} (${f.Pais}/${f.Gerencia}): venta ${n(V(f))}, `;
  ctx += `ppto ${n(P(f))}, año anterior ${n(L(f))}, `;
  ctx += `cumplimiento ${PP(f)}%, vs AA ${PA(f)}%, `;
  ctx += `cartera ${f.Cartera}, activacion ${f.Activacion}\n`;
}

return [{ json: {
  tarjeta: card, contexto: ctx,
  pregunta: p.pregunta, sesion: p.sesion, numero: p.numero,
  anio: p.anio, mes: p.mes, unidad: p.unidad,
  filtro: p.filtro, detalle: p.detalle, filas: filas.length
}}];

