if (!campo) {
  throw new Error('Sin binario del render');
}

// lee el archivo aunque n8n lo tenga en disco (filesystem-v2)
const buffer = await this.helpers.getBinaryDataBuffer(0, campo);
const b64 = buffer.toString('base64');

const p = $('Analizar mensaje').first().json;
const MESES = ['','enero','febrero','marzo','abril','mayo','junio',
  'julio','agosto','septiembre','octubre','noviembre','diciembre'];

return [{ json: {
  number:    $('Preparar entrada').first().json.numero,
  mediatype: 'image',
  mimetype:  'image/png',
  fileName:  `reporte_${p.anio}_${String(p.mes).padStart(2,'0')}.png`,
  caption:   `Reporte comercial · ${MESES[p.mes]} ${p.anio}`,
