// Verificacion en dos pasos:
//   1) la persona escribe su CODIGO DE EMPLEADO (debe ser el de su numero)
//   2) le llega un codigo de 6 digitos a su correo corporativo y lo escribe
// Verificado queda activo hasta la medianoche de Guatemala.
// Estado del proceso en Redis otp:{numero} -> { fase: 'empleado' | 'correo', ... }

const EMPLEADOS = [
  { numero: '50248664480', codigo: '002295', correo: 'awaight@productosbyb.com',    saludo: 'Bienvenida, Ana' },
  { numero: '50232134653', codigo: '004156', correo: 'aozler@productosbyb.com',     saludo: 'Bienvenido, Altan' },
  { numero: '50258077538', codigo: '004294', correo: 'jchitamul@productosbyb.com',  saludo: 'Bienvenido, Jeffrey' },
  { numero: '50240582026', codigo: '004298', correo: 'fcastaneda@productosbyb.com', saludo: 'Bienvenido, Felipe' },
  { numero: '50230694290', codigo: '004384', correo: 'asambrano@productosbyb.com',  saludo: 'Bienvenido, Axel' },
];
const VIGENCIA_OTP = 600;   // 10 min para escribir el codigo del correo
const VENTANA      = 900;   // 15 min para contar intentos del codigo de empleado
const MAX_INTENTOS = 3;
const BLOQUEO      = 900;   // 15 min tras 3 fallos

const e = $('Preparar entrada').first().json;
const numero = e.numero;
const texto  = e.texto || '';
const ahora  = Math.floor(Date.now() / 1000);
const leer   = v => { if (!v) return null; try { return typeof v === 'string' ? JSON.parse(v) : v; } catch (x) { return null; } };
const plural = (n, s, p) => `${n} ${n === 1 ? s : p}`;

const emp = EMPLEADOS.find(x => x.numero === numero);
if (!emp) {
  return [{ json: { estado: 'recordar', numero, output: 'Este número no está registrado para usar LIB-IA.' } }];
}

// 1) Sesion vigente
// Se lee de cada nodo por nombre: el Redis GET no conserva lo que traia el nodo anterior
const sesion = leer($('Auth GET').first().json.auth);
if (sesion) {
  return [{ json: { estado: 'ok', numero, empleado: { codigo: emp.codigo, correo: emp.correo } } }];
}

const otp = leer($('OTP GET').first().json.otp) || {};
const authTtl = Math.max(60, 86400 - ((ahora - 6 * 3600) % 86400));  // hasta medianoche GT

// 2) Bloqueado
if (otp.bloqueado) {
  const min = Math.max(1, Math.ceil((otp.expira - ahora) / 60));
  return [{ json: { estado: 'recordar', numero,
    output: `⏳ Por seguridad, el acceso está pausado. Intente de nuevo en ${plural(min, 'minuto', 'minutos')}.` } }];
}

const bloquear = () => ({ estado: 'fallo', numero,
  otpValor: JSON.stringify({ bloqueado: true, expira: ahora + BLOQUEO }), otpTtl: BLOQUEO,
  output: '⛔ Se agotaron los intentos. Por seguridad, podrá intentarlo de nuevo en 15 minutos.' });

// 3) Paso 2: esperando el codigo que se envio al correo
if (otp.fase === 'correo') {
  const escrito = (texto.match(/\b\d{6}\b/) || [])[0];

  if (!escrito) {
    return [{ json: { estado: 'recordar', numero,
      output: '📧 Escriba el código de 6 dígitos que le enviamos a su *correo corporativo*.' } }];
  }
  if (escrito === otp.codigo) {
    return [{ json: { estado: 'nuevo', numero, authTtl,
      authValor: JSON.stringify({ codigo: emp.codigo, desde: new Date().toISOString() }),
      output: `✅ *Acceso verificado*\n\n${emp.saludo}.\nSu acceso queda activo hasta la medianoche.\n\n¿Qué desea consultar? Por ejemplo: _¿cómo vamos?_` } }];
  }
  if (escrito === emp.codigo) {   // volvio a escribir su codigo de empleado: no cuenta como fallo
    return [{ json: { estado: 'recordar', numero,
      output: '👍 Ese es su código de empleado. Ahora escriba el código de 6 dígitos que le llegó a su *correo corporativo*.' } }];
  }
  const intentos = (otp.intentos || 0) + 1;
  if (intentos >= MAX_INTENTOS) return [{ json: bloquear() }];
  return [{ json: { estado: 'fallo', numero,
    otpValor: JSON.stringify({ ...otp, intentos }), otpTtl: Math.max(1, otp.expira - ahora),
    output: `❌ El código no es correcto. Le ${MAX_INTENTOS - intentos === 1 ? 'queda' : 'quedan'} ${plural(MAX_INTENTOS - intentos, 'intento', 'intentos')}.` } }];
}

// 4) Paso 1: pedir / validar el codigo de empleado
const candidatos = (texto.match(/\b\d{3,6}\b/g) || []).map(c => c.padStart(6, '0'));

if (candidatos.includes(emp.codigo)) {
  const codigo = String(Math.floor(100000 + Math.random() * 900000));
  return [{ json: { estado: 'enviar', numero, correo: emp.correo, codigo,
    otpValor: JSON.stringify({ fase: 'correo', codigo, intentos: 0, expira: ahora + VIGENCIA_OTP }),
    otpTtl: VIGENCIA_OTP,
    output: '📧 Gracias. Le enviamos un código de verificación a su *correo corporativo*.\n\nEscríbalo aquí para continuar. Vence en 10 minutos.' } }];
}

if (candidatos.length) {   // escribio un numero pero no es su codigo
  const intentos = (otp.fase === 'empleado' ? (otp.intentos || 0) : 0) + 1;
  if (intentos >= MAX_INTENTOS) return [{ json: bloquear() }];
  const expira = otp.fase === 'empleado' ? otp.expira : ahora + VENTANA;
  return [{ json: { estado: 'fallo', numero,
    otpValor: JSON.stringify({ fase: 'empleado', intentos, expira }), otpTtl: Math.max(1, expira - ahora),
    output: `❌ El código de empleado no es correcto. Le ${MAX_INTENTOS - intentos === 1 ? 'queda' : 'quedan'} ${plural(MAX_INTENTOS - intentos, 'intento', 'intentos')}.` } }];
}

return [{ json: { estado: 'recordar', numero,
  output: '🔐 *LIB-IA · Verificación de acceso*\n\nPara continuar, escriba su *código de empleado*.' } }];

