// Texto del detalle por vendedor / cliente / familia / producto.
// Lee las columnas de forma defensiva y calcula los % aqui,
// asi no depende de como se llamen exactamente en el proc.

const p = $('Analizar mensaje').first().json;
const filas = $input.all().map(i => i.json).filter(f => f && (f.Nombre || f.Clave));

const MESES = ['','enero','febrero','marzo','abril','mayo','junio',
  'julio','agosto','septiembre','octubre','noviembre','diciembre'];
const periodo = `${MESES[p.mes]} ${p.anio}`;
const TITULO = { VENDEDOR:'vendedor', CLIENTE:'cliente', FAMILIA:'familia', PRODUCTO:'producto' };
const esCajas = p.unidad === 'cajas';
const u = esCajas ? 'cajas' : 'Q';

if (!filas.length) {
  const que = p.termino ? `*${p.termino}*` : TITULO[p.nivel];
  return [{ json: { numero: p.numero,
    output: `No encontré información de ${que} para ${periodo}.\n\nPruebe con otro nombre, o escriba *${TITULO[p.nivel]}s* para ver los primeros 10.` } }];
}

const num  = (v) => Number(v) || 0;
const V    = (f) => num(esCajas ? f.Venta_Cajas : f.Venta_Valores);
const P    = (f) => num(esCajas ? f.Ppto_Cajas  : f.Ppto_Valores);
const L    = (f) => num(esCajas ? f.LY_Cajas    : f.LY_Valores);
const n0   = (v) => Math.round(v).toLocaleString('es-GT');
const sem  = (x) => x >= 100 ? '🟢' : x >= 85 ? '🟡' : '🔴';
const mk   = (x) => x >= 100 ? '+'  : x >= 85 ? '~'  : '!';
const corta = (s, n) => { s = String(s || '').trim(); return s.length > n ? s.slice(0, n - 1) + '…' : s; };

// totales de lo mostrado
const tV = filas.reduce((a,f) => a + V(f), 0);
const tP = filas.reduce((a,f) => a + P(f), 0);
const tL = filas.reduce((a,f) => a + L(f), 0);
const tPct = tP ? tV / tP * 100 : 0;
const tAA  = tL ? (tV / tL * 100 - 100) : null;

const peores = p.top < 0;
const enc = p.termino
  ? `*${TITULO[p.nivel].toUpperCase()}: ${p.termino.toUpperCase()}*`
  : `*${peores ? 'MENOR VENTA' : 'MAYOR VENTA'} POR ${TITULO[p.nivel].toUpperCase()}*`;

let out = `${enc}\n_${periodo} · ${esCajas ? 'Cajas' : 'Valores'}_\n\n`;
out += `> Venta *${n0(tV)}* ${u}\n`;
if (tP) out += `> Meta  ${n0(tP)} ${u}\n> ${sem(tPct)} *${tPct.toFixed(1)}%* del presupuesto\n`;
if (tAA !== null) out += `> ${tAA >= 0 ? '▲' : '▼'} ${tAA.toFixed(1)}% vs año anterior\n`;

// tabla monospace: nombre | venta | %ppto
const ANCHO = 20;
let tabla = 'NOMBRE'.padEnd(ANCHO) + 'VENTA'.padStart(8) + '  %PPTO\n';
tabla += '─'.repeat(ANCHO + 15) + '\n';
for (const f of filas) {
  const pct = P(f) ? V(f) / P(f) * 100 : null;
  tabla += corta(f.Nombre || f.Clave, ANCHO - 1).padEnd(ANCHO)
        + n0(V(f)).padStart(8)
        + (pct === null ? '      -' : (mk(pct) + pct.toFixed(1).padStart(6))) + '\n';
}

out += '\n```\n' + tabla + '```\n';

if (!p.termino) {
  out += `_Los ${Math.abs(p.top)} de ${peores ? 'menor' : 'mayor'} venta_\n`;
}
if (filas[0] && filas[0].Gerencia && p.nivel !== 'FAMILIA' && p.nivel !== 'PRODUCTO') {
  const gs = [...new Set(filas.map(f => f.Gerencia).filter(Boolean))];
  if (gs.length === 1) out += `_Gerencia: ${gs[0]}_\n`;
}
out += `\n_Escriba por ejemplo:_ _cliente walmart_ _·_ _familia mayonesa_`;

return [{ json: { numero: p.numero, output: out } }];
